const $=id=>document.getElementById(id),KEY='council-crown-game-release-v0.6.0';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,active=0,cellId=0,role='economy',regimentId=null,moving=false,saveBlocked=false,camera={x:0,y:0,w:1200,h:700};
function newGame(seed){return Game.create(generateStudentWorld(seed,GRIA_TEMPLATE));}
try{const raw=localStorage.getItem(KEY);state=raw?Game.validate(JSON.parse(raw)):newGame(73819);}catch(e){state=newGame(73819);saveBlocked=true;$('notice').textContent='Saved campaign could not be read. Autosave paused to protect it; download this campaign or open a valid save.';}
function notify(s){$('notice').textContent=s;}
function save(){if(saveBlocked)return;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify('Storage unavailable or full. Save campaign downloads a backup.');}}
function action(fn,message){try{fn();save();render();if(message)notify(message);}catch(e){notify(e.message);}}
function ctry(){return state.countries[active];}function regiment(){return state.regiments.find(r=>r.id===regimentId&&r.country===active&&r.troops>0);}
function options(items,value){return items.map(([id,name])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`).join('');}
function field(label,id,items,value,hint=''){return `<label class="field">${label}<select id="${id}">${options(items,value)}</select><small>${hint}</small></label>`;}
function render(){const c=ctry(),y=Game.totals(state,active);$('country').innerHTML=options(state.countries.map(c=>[c.id,c.name]),active);$('turn').textContent=String(state.turn).padStart(2,'0');$('season').textContent=['SPRING','SUMMER','AUTUMN','WINTER'][(state.turn-1)%4]+' · YEAR '+(1+Math.floor((state.turn-1)/4));$('stats').innerHTML=Game.goods.map(k=>`<div class="stat"><small>${k==='money'?'Treasury':k}</small><strong>${Math.floor(c.stock[k]).toLocaleString()}</strong><span>+${y[k].toFixed(1)} gross / turn</span></div>`).join('')+`<div class="stat"><small>Public morale</small><strong>${Math.round(c.morale)}<small> /100</small></strong><span>Policies & shortages</span></div><div class="stat"><small>Population</small><strong>${y.population.toLocaleString()}</strong><span>Workers & recruits</span></div>`;
$('legend').replaceChildren(...state.biomes.filter(Boolean).map(b=>{const el=document.createElement('span'),i=document.createElement('i');i.style.background=b.color;el.append(i,document.createTextNode(b.name));return el;}));$('cellNumber').max=state.cells.length-1;$('cellNumber').value=cellId;renderCell();renderRole();draw();$('reports').innerHTML=state.log.length?state.log.map(l=>`<details ${l===state.log[0]?'open':''}><summary>Turn ${esc(l.turn)} · Council report</summary><ul>${l.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></details>`).join(''):'<div class="empty">The story starts with your first decision. Advance a turn to see production, discoveries, and encounters here.</div>';}
function renderCell(){const cell=state.cells[cellId],y=Game.output(state,cell),owner=state.countries[cell.country];$('cell').innerHTML=`<h3>Cell ${cell.id} · ${esc(cell.biome.name)}</h3><p>${owner?esc(owner.name):'Unclaimed waters / wilderness'} · ${cell.population} residents${cell.occupation?' · Occupied: reduced output':''}</p><div class="yields">${Game.goods.map(k=>`<span>${esc(k)} +${y[k].toFixed(1)}</span>`).join('')}</div><p>${cell.settlement?'Settlement: '+esc(cell.settlement)+' · ':''}Buildings: ${cell.buildings.map(b=>Game.buildings[b].name).join(', ')||'Undeveloped'}${cell.construction?` · ${Game.buildings[cell.construction.type].name}: ${cell.construction.remaining} turns remaining`:''}</p><p>${state.regiments.filter(r=>r.cell===cellId&&r.troops>0).map(r=>`${esc(r.name)} (${r.troops} troops)`).join(' · ')||'No regiments stationed here.'}</p>`;}
function renderRole(){const c=ctry();document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===role));let html='';if(role==='economy'){html=`<p class="role-intro">Balance today's needs with tomorrow's prosperity. Building costs are reserved immediately. Wood builds, metal equips, cloth supports schools and armies.</p>${field('Economic policy','economicPolicy',[['balanced','Balanced budget'],['taxation','High taxation · +30% revenue, −3 morale'],['relief','Public relief · −25% revenue, +3 morale']],c.economy,'Active each turn. Research education policy also changes morale.')}<label class="field">Research funding per turn<input id="funding" type="number" min="0" max="100" value="${c.funding}"><small>Funded after upkeep, up to the money available.</small></label><label class="field">Military recruitment allowance<input id="allowance" type="number" min="0" max="200" value="${c.militaryBudget}"><small>Permission to spend from the shared treasury. Recruitment draws this allowance down; it is not extra money.</small></label><h3>Develop selected cell ${cellId}</h3><div class="cards">${Object.entries(Game.buildings).map(([id,b])=>`<div class="mini-card"><strong>${b.name}</strong><p>${Game.goods.filter(k=>b[k]).map(k=>Economy.icons[k]+' '+b[k]+' '+k).join(' · ')} · ${b.turns} turns</p><button data-build="${id}" ${state.cells[cellId].country!==active||!state.cells[cellId].land?'disabled':''}>${['city','village'].includes(id)?'Propose to council':'Start construction'}</button></div>`).join('')}</div>`;}
if(role==='research'){const p=Game.projects[c.focus],need=p.cost*(c.tech[c.focus]+1);html=`<p class="role-intro">Education shapes the workforce. Research improves food, production, or equipment for the whole country.</p>${field('Education policy','education',[['schools','Public schools · +1 morale'],['workshops','Vocational institutes · +25% research, −1 morale'],['academies','Intensive academies · +50% research, −2 morale']],c.education)}${field('Research focus','focus',Object.entries(Game.projects).map(([k,p])=>[k,p.name]),c.focus,'Changing focus resets unfinished progress. Completed levels remain.')}<div class="mini-card"><strong>${p.name} · Level ${c.tech[c.focus]+1}</strong><p>${p.description}. Budget: ${c.funding} money per turn.</p><progress value="${c.progress}" max="${need}"></progress><p>${c.progress.toFixed(1)} / ${need} research points</p></div><h3>National capabilities</h3>${Object.entries(Game.projects).map(([k,p])=>`<p>${p.name}: <b>Level ${c.tech[k]}</b><br><small>${p.description}</small></p>`).join('')}<p class="role-intro">Schools add research points, up to +3 per turn. Larger projects cost more with each level. Seasons are a calendar only in this first prototype.</p>`;}
if(role==='military'){const units=state.regiments.filter(r=>r.country===active&&r.troops>0);if(!regiment()&&units.length)regimentId=units[0].id;const r=regiment();html=`<p class="role-intro">Issue a destination, then set engagement rules. One cell per turn; taiga, tundra, and glaciers take two turns.</p>${r?`${field('Regiment','regiment',units.map(r=>[r.id,r.name]),r.id)}<div class="mini-card"><strong>${r.troops} infantry · Cell ${r.cell}</strong><p>Readiness ${r.readiness}% · Carried food ${r.supply.toFixed(1)}<br>${r.order?'Moving toward cell '+r.order.destination:'Holding position'}</p></div>${field('Engagement orders','stance',[['defend','Defend only'],['avoid','Avoid combat / withdraw'],['target','Attack named country'],['all','Attack any non-ally']],r.stance)}${r.stance==='target'?field('Attack target','target',state.countries.filter(c=>c.id!==active).map(c=>[c.id,c.name]),r.target):''}<div class="actions"><button id="move" class="primary">${moving?'Click destination on map…':'Choose destination'}</button><button id="cancelOrder">Hold position</button></div><div class="actions"><button id="recruit">Recruit 10 infantry</button><button id="split">Split regiment</button></div><small>Recruit: 20 money, 8 metal, 4 cloth, 10 residents; requires at least 30 residents. Costs depend on troop type. Troop transfers require both regiments to share a cell.</small>`:'<p>No surviving regiments. Create a new guard at your selected owned cell.</p><button id="newGuard">Create empty guard</button>'}<hr><h3>Diplomatic desk</h3>${field('Other country','partner',state.countries.filter(x=>x.id!==active).map(x=>[x.id,x.name]),state.countries.find(x=>x.id!==active)?.id)}<div class="actions"><button id="ally">Offer alliance</button><button id="peace">Offer peace</button><button id="war">Declare war</button></div><p id="relation"></p>${state.offers.map((o,i)=>o.to===active?`<div class="mini-card"><p>${esc(state.countries[o.from].name)} offers ${o.kind==='ally'?'an alliance':'peace'}.</p><button data-accept="${i}">Accept agreement</button><button data-decline="${i}">Decline</button></div>`:'').join('')}<p class="role-intro">Switch councils to accept offers. Sharing a cell is peaceful unless an engagement order starts combat. Allies are never attacked.</p>`;}
$('rolePanel').innerHTML=html;const change=(id,fn)=>{if($(id))$(id).onchange=e=>action(()=>fn(e.target.value));};change('economicPolicy',v=>c.economy=v);change('funding',v=>c.funding=Math.max(0,Math.min(100,Number(v)||0)));change('allowance',v=>c.militaryBudget=Math.max(0,Math.min(200,Number(v)||0)));change('education',v=>c.education=v);change('focus',v=>{if(c.focus!==v){c.focus=v;c.progress=0;}});document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>action(()=>Game.build(state,active,cellId,b.dataset.build),'Construction queued.'));change('regiment',v=>{regimentId=Number(v);moving=false;});change('stance',v=>{regiment().stance=v;if(v==='target'&&regiment().target===null)regiment().target=state.countries.find(c=>c.id!==active).id;});change('target',v=>regiment().target=Number(v));const click=(id,fn,msg)=>{if($(id))$(id).onclick=()=>action(fn,msg);};click('move',()=>{moving=true;},'Click a land cell, or enter its number and choose Inspect, to issue a movement order.');click('cancelOrder',()=>{regiment().order=null;moving=false;},'Regiment will hold position.');click('recruit',()=>Game.recruit(state,regimentId),'10 infantry recruited.');click('split',()=>Game.split(state,regimentId),'Troops and supplies divided between two regiments.');click('newGuard',()=>{if(state.cells[cellId].country!==active)throw Error('Select your own land cell.');if(state.cells[cellId].population<30||c.stock.metal<8||c.stock.cloth<4||c.stock.money<20||c.militaryBudget<20)throw Error('Need 30 residents, 8 metal, 4 cloth, 20 money and military allowance.');state.regiments.push({id:state.nextId++,country:active,cell:cellId,name:c.name+' New Guard',troops:0,supply:10,readiness:60,order:null,stance:'defend',target:null});regimentId=state.nextId-1;Game.recruit(state,regimentId);});click('ally',()=>Game.offer(state,active,Number($('partner').value),'ally'),'Alliance offered. Switch councils to accept.');click('peace',()=>Game.offer(state,active,Number($('partner').value),'neutral'),'Peace offered. Switch councils to accept.');click('war',()=>{state.relations[[active,Number($('partner').value)].sort((a,b)=>a-b).join('-')]='enemy';},'War declared. Set regiment engagement orders separately.');const rel=()=>{if($('relation'))$('relation').textContent='Current relationship: '+Game.relation(state,active,Number($('partner').value));};if($('partner'))$('partner').onchange=rel;rel();document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>action(()=>Game.accept(state,Number(b.dataset.accept),active),'Agreement accepted.'));document.querySelectorAll('[data-decline]').forEach(b=>b.onclick=()=>action(()=>state.offers.splice(Number(b.dataset.decline),1),'Offer declined.'));}
const ctx=$('map').getContext('2d');function poly(c){ctx.beginPath();c.polygon.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();}
function draw(){ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#466eab';ctx.fillRect(0,0,1200,700);ctx.scale(1200/camera.w,700/camera.h);ctx.translate(-camera.x,-camera.y);const z=camera.w/1200;state.cells.forEach(c=>{if(!c.land)return;poly(c);ctx.fillStyle=$('layer').value==='political'?(state.countries[c.country]?.color||'#abb398'):$('layer').value==='food'?`hsl(${45+Math.min(1,Game.output(state,c).food/3)*65} 40% 65%)`:c.biome.color;ctx.fill();ctx.strokeStyle=c.country===active?'#253d3844':'#253d381c';ctx.lineWidth=.6*z;ctx.stroke();});state.cells.forEach(c=>{if(!c.land)return;c.neighbors.forEach(n=>{const b=state.cells[n];if(b.land&&b.country!==c.country){poly(c);ctx.strokeStyle='#233e3266';ctx.lineWidth=.8*z;ctx.stroke();}});});if(state.cells[cellId]){poly(state.cells[cellId]);ctx.fillStyle='#fff7b077';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2*z;ctx.stroke();}const r=regiment();if(r?.order){ctx.beginPath();ctx.moveTo(...state.cells[r.cell].point);(Game.path(state,r.cell,r.order.destination,r.country)||[]).forEach(id=>ctx.lineTo(...state.cells[id].point));ctx.strokeStyle='#fff2bb';ctx.lineWidth=2*z;ctx.setLineDash([5*z,4*z]);ctx.stroke();ctx.setLineDash([]);}state.countries.forEach(c=>{ctx.font=`bold ${12*z}px sans-serif`;ctx.textAlign='center';ctx.lineWidth=3*z;ctx.strokeStyle='#f9fbec';ctx.fillStyle='#263f34';ctx.strokeText(c.name,...c.capital);ctx.fillText(c.name,...c.capital);});state.regiments.filter(r=>r.troops>0).forEach(r=>{const p=state.cells[r.cell].point;ctx.beginPath();ctx.arc(...p,5*z,0,Math.PI*2);ctx.fillStyle=r.country===active?'#183b32':'#b07846';ctx.fill();ctx.strokeStyle='#fff8dd';ctx.lineWidth=1.5*z;ctx.stroke();});ctx.setTransform(1,0,0,1,0,0);}
function selectCell(id){if(!Number.isInteger(id)||!state.cells[id])return notify('Choose a valid cell number.');cellId=id;if(moving){action(()=>{Game.move(state,regimentId,id);moving=false;},'Movement order saved. It resolves when the turn advances.');}else render();}
function mapPoint(e){const b=$('map').getBoundingClientRect();return [camera.x+(e.clientX-b.left)/b.width*camera.w,camera.y+(e.clientY-b.top)/b.height*camera.h];}
function contains(p,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
let drag=null;$('map').onpointerdown=e=>{if(e.shiftKey){drag={x:e.clientX,y:e.clientY,c:{...camera}};$('map').setPointerCapture(e.pointerId);}};$('map').onpointermove=e=>{if(drag){const b=$('map').getBoundingClientRect();camera.x=drag.c.x-(e.clientX-drag.x)/b.width*camera.w;camera.y=drag.c.y-(e.clientY-drag.y)/b.height*camera.h;draw();}};$('map').onpointerup=e=>{if(drag){drag=null;return;}const p=mapPoint(e),c=state.cells.find(c=>contains(p,c.polygon));if(c)selectCell(c.id);};function zoom(f){const w=Math.max(120,Math.min(1200,camera.w*f)),h=w*700/1200;camera.x+=(camera.w-w)/2;camera.y+=(camera.h-h)/2;camera.w=w;camera.h=h;draw();}$('map').onwheel=e=>{e.preventDefault();zoom(e.deltaY>0?1.15:.87);};$('zoomIn').onclick=()=>zoom(.75);$('zoomOut').onclick=()=>zoom(1.3);$('resetView').onclick=()=>{camera={x:0,y:0,w:1200,h:700};draw();};$('layer').onchange=draw;$('inspect').onclick=()=>selectCell(Number($('cellNumber').value));$('country').onchange=e=>{active=Number(e.target.value);regimentId=null;moving=false;cellId=state.cells.find(c=>c.country===active&&c.buildings.includes('city'))?.id||0;render();};document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;moving=false;renderRole();});$('advance').onclick=()=>$('turnDialog').showModal();$('cancelTurn').onclick=()=>$('turnDialog').close();$('confirmTurn').onclick=()=>{$('turnDialog').close();action(()=>{Game.advance(state);moving=false;},'Turn resolved. Review the campaign chronicle below.');};
$('newWorld').onclick=()=>{if(!confirm('Start a separate new campaign? Download your current campaign first to preserve it.'))return;state=newGame(crypto.getRandomValues(new Uint32Array(1))[0]);active=0;cellId=0;regimentId=null;saveBlocked=false;save();render();notify('New biome world ready. All countries are available in the council selector.');};$('download').onclick=()=>{const blob=new Blob([JSON.stringify(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`council-crown-turn-${state.turn}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};async function loadFile(e,importing){const file=e.target.files[0];if(!file)return;try{if(file.size>35*1024*1024)throw Error('Choose a JSON file smaller than 35 MB.');const raw=JSON.parse(await file.text()),next=importing?Game.create(importAzgaarWorld(raw)):Game.validate(raw);if(!confirm('Replace this game campaign? Download it first if you want to keep it.'))return;state=next;active=0;cellId=0;regimentId=null;saveBlocked=false;moving=false;camera={x:0,y:0,w:1200,h:700};save();render();notify(importing?'Full Azgaar geometry and biomes imported. Game resources are newly generated prototype values.':'Campaign restored.');}catch(e){notify(e.message);}finally{e.target.value='';}}$('importButton').onclick=()=>$('import').click();$('restoreButton').onclick=()=>$('restore').click();$('import').onchange=e=>loadFile(e,true);$('restore').onchange=e=>loadFile(e,false);cellId=state.regiments[0]?.cell||0;render();
